css:
:where(.wtyg-map-site_animal_fighting) *{margin: 0; padding: 0; box-sizing: border-box;}
:where(.wtyg-map-site_animal_fighting){background: #0a0a0a; overflow: hidden;}
:where(.wtyg-map-site_animal_fighting) .animal-fight-map{width: 100%;
    height: 1000px; 
    position: relative;
    background: #0a0a0a;
    border-radius: 12px;
    overflow: hidden; 
    margin: 20px 0;}
:where(.wtyg-map-site_animal_fighting) .animal-fight-map *{margin: 0; padding: 0; box-sizing: border-box;}
:where(.wtyg-map-site_animal_fighting) :is([data-wtyg-id="fightMap"],#wtyg-noid-fightMap){height: 100%; width: 100%; position: absolute; top: 0; left: 0;}
:where(.wtyg-map-site_animal_fighting) .fight-header{position: absolute; top: 20px; left: 50%; transform: translateX(-50%); z-index: 1000;
    background: rgba(0, 0, 0, 0.95); backdrop-filter: blur(10px); padding: 18px 35px;
    border-radius: 10px; border: 1px solid rgba(255, 255, 255, 0.1);
    text-align: center; max-width: 90%;}
:where(.wtyg-map-site_animal_fighting) .fight-header h1{font-size: 26px; font-weight: 700; margin-bottom: 6px;
    background: linear-gradient(135deg, #ff0000, #cc0000);
    -webkit-background-clip: text; -webkit-text-fill-color: transparent; color: #ff0000;}
:where(.wtyg-map-site_animal_fighting) .fight-header p{font-size: 12px; color: #aaa; line-height: 1.3;}
:where(.wtyg-map-site_animal_fighting) .disclaimer{font-size: 10px; color: #ff6666; margin-top: 6px; font-weight: 600;}
:where(.wtyg-map-site_animal_fighting) .fight-filters{position: absolute; top: 130px; left: 20px; z-index: 1000;
    background: rgba(0, 0, 0, 0.95); backdrop-filter: blur(10px); padding: 15px;
    border-radius: 10px; border: 1px solid rgba(255, 255, 255, 0.1);
    width: 260px;
    max-height: calc(100% - 220px); 
    overflow-y: auto; overflow-x: hidden;}
:where(.wtyg-map-site_animal_fighting) .fight-filters::-webkit-scrollbar{width: 6px;}
:where(.wtyg-map-site_animal_fighting) .fight-filters::-webkit-scrollbar-track{background: rgba(255, 255, 255, 0.05); border-radius: 3px;}
:where(.wtyg-map-site_animal_fighting) .fight-filters::-webkit-scrollbar-thumb{background: rgba(255, 255, 255, 0.2); border-radius: 3px;}
:where(.wtyg-map-site_animal_fighting) .fight-filters h3{font-size: 15px; margin-bottom: 12px; color: #fff; font-weight: 600;}
:where(.wtyg-map-site_animal_fighting) .fg{margin-bottom: 8px;}
:where(.wtyg-map-site_animal_fighting) .fg label{display: flex; align-items: center; padding: 6px 8px; cursor: pointer;
    border-radius: 5px; transition: all 0.2s; font-size: 13px; color: #fff;}
:where(.wtyg-map-site_animal_fighting) .fg label:hover{background: rgba(255, 255, 255, 0.05);}
:where(.wtyg-map-site_animal_fighting) .fg input{margin-right: 8px; width: 14px; height: 14px; cursor: pointer; flex-shrink: 0;}
:where(.wtyg-map-site_animal_fighting) .fg .cn{margin-left: auto; font-size: 11px; color: #888;
    background: rgba(255, 255, 255, 0.1); padding: 2px 6px; border-radius: 8px; flex-shrink: 0;}
:where(.wtyg-map-site_animal_fighting) .illegal-text{color: #ff6666 !important;}
:where(.wtyg-map-site_animal_fighting) .fight-stats{position: absolute; bottom: 20px; left: 20px; z-index: 1000;
    background: rgba(0, 0, 0, 0.95); backdrop-filter: blur(10px); padding: 12px 18px;
    border-radius: 10px; border: 1px solid rgba(255, 255, 255, 0.1); font-size: 13px; color: #fff;}
:where(.wtyg-map-site_animal_fighting) .fight-stats strong{color: #ff0000; font-size: 18px;}
:where(.wtyg-map-site_animal_fighting) .leaflet-popup-content-wrapper{background: rgba(0, 0, 0, 0.95) !important; color: #fff !important; border-radius: 8px !important;}
:where(.wtyg-map-site_animal_fighting) .leaflet-popup-content{margin: 15px !important; font-size: 14px !important; color: #fff !important;}
:where(.wtyg-map-site_animal_fighting) .leaflet-popup-content h4{margin: 0 0 8px 0 !important; font-size: 16px !important; color: #ff0000 !important;}
:where(.wtyg-map-site_animal_fighting) .leaflet-popup-tip{background: rgba(0, 0, 0, 0.95) !important;}
@media (max-width: 768px){:where(.wtyg-map-site_animal_fighting) .animal-fight-map{height: 600px;}
:where(.wtyg-map-site_animal_fighting) .fight-header{top: 10px; left: 10px; right: 10px; transform: none; padding: 12px; max-width: none;}
:where(.wtyg-map-site_animal_fighting) .fight-header h1{font-size: 18px;}
:where(.wtyg-map-site_animal_fighting) .fight-filters{top: auto; bottom: 60px; left: 10px; right: 10px; width: auto;
        max-height: 40vh;}
:where(.wtyg-map-site_animal_fighting) .fight-stats{left: 10px; right: 10px; bottom: 10px;}}
